function SettingsPage({data,refresh,toast}){
  const [settings,S]=useState(safeSettings(data.settings)),[platforms,P]=useState((data.settings.platforms||[]).join('\n')),[categories,C]=useState((data.settings.expense_categories||[]).join('\n')),[shiftConfig,ShiftConfig]=useState((data.settings.shift_types||[]).map(x=>`${x.name},${x.start},${x.end},${x.rate??''}`).join('\n'));
  useEffect(()=>{S(safeSettings(data.settings));P((data.settings.platforms||[]).join('\n'));C((data.settings.expense_categories||[]).join('\n'));ShiftConfig((data.settings.shift_types||[]).map(x=>`${x.name},${x.start},${x.end},${x.rate??''}`).join('\n'));},[data.settings]);
  const save=async event=>{event.preventDefault();const nextPlatforms=platforms.split('\n').map(x=>x.trim()).filter(Boolean),nextCategories=categories.split('\n').map(x=>x.trim()).filter(Boolean),nextShiftTypes=shiftConfig.split('\n').map(x=>x.trim()).filter(Boolean).map((line,i)=>{const [name,start,end,rate]=line.split(',').map(x=>x.trim());return{name,start,end,rate:rate||null,color:(settings.shift_types||[])[i]?.color||'#86b99a'};});if(!nextPlatforms.length||!nextCategories.length||!nextShiftTypes.length){toast('Keep at least one platform, category, and shift type.');return;}try{await api('/settings',{method:'PUT',body:JSON.stringify({...settings,platforms:nextPlatforms,expense_categories:nextCategories,shift_types:nextShiftTypes})});await refresh();toast('Settings saved to your account.');}catch(e){toast(e.message);}};
  const togglePlatform=name=>S(prev=>({...prev,disabled_platforms:prev.disabled_platforms.includes(name)?prev.disabled_platforms.filter(x=>x!==name):[...prev.disabled_platforms,name]}));
  return <><PageIntro title="Platform & Category Settings" detail="Edit the workbook Lists tab, manage shift defaults and set display preferences."/><form className="card form-card settings-form" onSubmit={save}><SectionHead title="Platforms and expense categories" detail="Reorder by moving lines. Disable a platform to hide it from new entries; historical rows remain unchanged."/><div className="settings-grid"><label>Delivery platforms<textarea rows="7" value={platforms} onChange={e=>P(e.target.value)} placeholder="One platform per line"/></label><label>Expense categories<textarea rows="7" value={categories} onChange={e=>C(e.target.value)} placeholder="One category per line"/></label><div className="platform-toggles"><b>Enabled platforms</b>{platforms.split('\n').map(x=>x.trim()).filter(Boolean).map(name=><label key={name}><input type="checkbox" checked={!settings.disabled_platforms.includes(name)} onChange={()=>togglePlatform(name)}/>{name}</label>)}</div><div className="form-divider">FINANCIAL &amp; DISPLAY PREFERENCES</div><FormField label="Monthly income goal" type="number" min="0" value={settings.monthly_goal} onChange={v=>S({...settings,monthly_goal:v})}/><FormField label="Currency" value={settings.currency} options={['EUR','USD','GBP']} onChange={v=>S({...settings,currency:v})}/><FormField label="Distance unit" value={settings.distance_unit} options={[{value:'km',label:'Kilometres (km)'},{value:'mi',label:'Miles (mi)'}]} onChange={v=>S({...settings,distance_unit:v})}/><FormField label="Date format" value={settings.date_format} options={['dd/MM/yyyy','MM/dd/yyyy','yyyy-MM-dd']} onChange={v=>S({...settings,date_format:v})}/><FormField label="Theme" value={settings.theme} options={['light','dark']} onChange={v=>S({...settings,theme:v})}/><FormField label="Timezone" value={settings.timezone} options={['Europe/Vilnius','Europe/Riga','Europe/Tallinn','Europe/London','Europe/Dublin','UTC']} onChange={v=>S({...settings,timezone:v})}/><FormField label="Fuel calculation" value={settings.fuel_method} options={[{value:'split',label:'Fill-up split'},{value:'average',label:'Car average'}]} onChange={v=>S({...settings,fuel_method:v})}/><FormField label="Manual average (L/100 km)" type="number" min="0" value={settings.avg_consumption||''} onChange={v=>S({...settings,avg_consumption:v})}/><FormField label="Manual fuel cost per km (€)" type="number" min="0" value={settings.manual_cost_per_km||''} onChange={v=>S({...settings,manual_cost_per_km:v})}/><div className="form-divider">CONFIGURABLE SHIFT TYPES</div><label className="span-two">One shift per line: name,start,end,optional €/hour override. Overnight times are supported.<textarea rows="6" value={shiftConfig} onChange={e=>ShiftConfig(e.target.value)} placeholder="Morning,07:00,15:00,\nNight,18:00,02:00,"/></label></div><div className="form-actions"><button className="primary">Save preferences and Lists →</button></div></form><section className="card"><SectionHead title="Your stored data" detail="Private records are loaded from PostgreSQL using your signed-in account."/><MetricGrid columns={3} items={[["Daily Log",data.logs.length,'Saved rows'],['Fuel fill-ups',data.fuel.length,'Saved fill-ups'],['Planned days',data.shifts.length,'Saved planner rows']]}/></section></>;
}

function parseWorkbook(book){
  const errors=[],readDate=value=>{if(value instanceof Date)return `${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}-${String(value.getDate()).padStart(2,'0')}`;if(typeof value==='number'){const d=XLSX.SSF.parse_date_code(value);return d?`${d.y}-${String(d.m).padStart(2,'0')}-${String(d.d).padStart(2,'0')}`:'';}if(typeof value==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(value))return value;const d=new Date(value);return Number.isNaN(d.getTime())?'':`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};
  const asTime=value=>{if(typeof value==='number'){const mins=Math.round(value*1440)%1440;return `${String(Math.floor(mins/60)).padStart(2,'0')}:${String(mins%60).padStart(2,'0')}`;}return typeof value==='string'&&/^\d{1,2}:\d{2}/.test(value)?value.slice(0,5):'';};
  const rows=(name,range)=>book.Sheets[name]?XLSX.utils.sheet_to_json(book.Sheets[name],{range,defval:''}):[];
  if(!book.Sheets['Daily Log'])errors.push('Missing required worksheet: Daily Log.');
  if(!book.Sheets.Fuel)errors.push('Missing required worksheet: Fuel.');
  const rawLogs=rows('Daily Log',4).map((r,i)=>({excelRow:i+6,source_key:`daily-${i+6}`,work_date:readDate(r.Date),platform:String(r.Platform||''),hours:r['Hours Worked'],orders_count:r['Orders / Deliveries'],odo_start:r['Odometer Start (km)'],odo_end:r['Odometer End (km)'],manual_km:r['Manual km (if no odometer)'],earnings:r['Earnings (€)'],tips:r['Tips / Bonus (€)'],fuel_override:r['Fuel Override (€) optional'],maintenance:r['Maintenance / Repairs (€)'],other_cost:r['Other Work Costs (€)'],personal_expense:r['Personal Expense (€)'],notes:r.Notes||''})).filter(x=>['platform','hours','orders_count','odo_start','odo_end','manual_km','earnings','tips','fuel_override','maintenance','other_cost','personal_expense','notes'].some(k=>x[k]!==''&&x[k]!=null));
  const logs=[];rawLogs.forEach(x=>{const bad=[];if(!/^\d{4}-\d{2}-\d{2}$/.test(x.work_date))bad.push('Date is missing or invalid');for(const key of ['hours','orders_count','odo_start','odo_end','manual_km','earnings','tips','fuel_override','maintenance','other_cost','personal_expense'])if(x[key]!==''&&x[key]!=null&&(!Number.isFinite(Number(x[key]))||Number(x[key])<0))bad.push(`${key.replaceAll('_',' ')} must be a non-negative number`);if(x.odo_start!==''&&x.odo_end!==''&&Number(x.odo_end)<Number(x.odo_start))bad.push('Odometer end is below start');if(!x.platform)bad.push('Platform is missing');if(bad.length)errors.push(`Daily Log row ${x.excelRow}: ${bad.join('; ')}`);else logs.push(x);});
  const rawFuel=rows('Fuel',10).map((r,i)=>({excelRow:i+12,source_key:`fuel-${i+12}`,fill_date:readDate(r.Date),odometer:r['Odometer (km)'],litres:r.Litres,total_paid:r['Total Paid (€)'],full_tank:r['Full Tank']===undefined?true:r['Full Tank'],station:r.Station||'',notes:r.Notes||''})).filter(x=>x.fill_date||x.odometer||x.litres||x.total_paid);
  const fuel=[];rawFuel.forEach(x=>{const bad=[];if(!/^\d{4}-\d{2}-\d{2}$/.test(x.fill_date))bad.push('Date is missing or invalid');for(const key of ['odometer','litres','total_paid'])if(x[key]!==''&&x[key]!=null&&(!Number.isFinite(Number(x[key]))||Number(x[key])<0))bad.push(`${key} must be non-negative`);if(bad.length)errors.push(`Fuel row ${x.excelRow}: ${bad.join('; ')}`);else fuel.push(x);});
  const planner=book.Sheets['Shift Planner'],plannerRows=rows('Shift Planner',13),year=Number(planner?.B2?.v),monthRaw=planner?.D2?.v,month=typeof monthRaw==='number'?monthRaw:(['jan','feb','mar','apr','may','jun','jul','aug','sep','oct','nov','dec'].indexOf(String(monthRaw).slice(0,3).toLowerCase())+1);
  const shiftData=rows('Shift Data',0),shifts=shiftData.length?shiftData.map(r=>({work_date:readDate(r.Date),shift1:r['Shift 1']||'',hours1:r['Hours 1']??'',shift2:r['Shift 2']||'',hours2:r['Hours 2']??'',notes:r.Notes||''})).filter(x=>/^\d{4}-\d{2}-\d{2}$/.test(x.work_date)) : plannerRows.map(r=>{const day=Number(r.Day);if(!year||!month||day<1||day>daysInMonth(year,month)||!r['Shift 1']&&!r['Shift 2']&&!r.Notes&&!r['Hours 1 (optional)']&&!r['Hours 2 (optional)'])return null;return{work_date:`${year}-${String(month).padStart(2,'0')}-${String(day).padStart(2,'0')}`,shift1:r['Shift 1']||'',hours1:r['Hours 1 (optional)'],shift2:r['Shift 2 (optional)']||'',hours2:r['Hours 2 (optional)'],notes:r.Notes||''};}).filter(Boolean);
  const platforms=rows('Lists',0).map(r=>r.Platforms).filter(Boolean),fuelSheet=book.Sheets.Fuel||{};
  let backupSettings=null;try{const raw=book.Sheets.Settings?.A1?.v;if(raw)backupSettings=JSON.parse(raw);}catch{errors.push('Settings backup is invalid JSON.');}const settings=backupSettings||{monthly_goal:book.Sheets.Dashboard?.L81?.v||1500,fuel_method:String(fuelSheet.D5?.v||'Fill-up split').toLowerCase().includes('average')?'average':'split',avg_consumption:fuelSheet.D6?.v||0,morning_start:asTime(planner?.D7?.v)||'07:00',morning_end:asTime(planner?.E7?.v)||'15:00',night_start:asTime(planner?.D8?.v)||'18:00',night_end:asTime(planner?.E8?.v)||'02:00',shift_types:[{name:'Morning',start:asTime(planner?.D7?.v)||'07:00',end:asTime(planner?.E7?.v)||'15:00',rate:null,color:'#86b99a'},{name:'Night',start:asTime(planner?.D8?.v)||'18:00',end:asTime(planner?.E8?.v)||'02:00',rate:null,color:'#7182a6'}],platforms:platforms.length?platforms:['Bolt','Wolt','Uber','Bolt/Wolt','Other']};
  const duplicateMap=new Map();for(const row of logs){const key=[row.work_date,row.platform,row.hours,row.orders_count,row.odo_start,row.odo_end,row.earnings,row.tips].join('|');duplicateMap.set(key,(duplicateMap.get(key)||0)+1);}const duplicates=[...duplicateMap].filter(([,n])=>n>1).map(([key])=>key);
  return {logs,fuel,shifts,settings,errors,duplicates};
}

function exportRows(filename,records,sheetName='Data'){
  const wb=XLSX.utils.book_new(),ws=XLSX.utils.json_to_sheet(records);XLSX.utils.book_append_sheet(wb,ws,sheetName);XLSX.writeFile(wb,filename);
}

function ImportExport({data,refresh,toast}){
  const [preview,Preview]=useState(null),[mode,Mode]=useState('append'),[busy,Busy]=useState(false);
  const select=async event=>{const file=event.target.files?.[0];if(!file)return;Busy(true);try{const book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});const parsed=parseWorkbook(book);const existing=new Set(data.logs.map(x=>[dateKey(x.work_date),x.platform,number(x.hours),number(x.orders_count),number(x.odo_start),number(x.odo_end),number(x.earnings),number(x.tips)].join('|')));parsed.duplicates=[...new Set([...parsed.duplicates,...parsed.logs.filter(x=>existing.has([x.work_date,x.platform,number(x.hours),number(x.orders_count),number(x.odo_start),number(x.odo_end),number(x.earnings),number(x.tips)].join('|'))).map(x=>`${x.work_date} · ${x.platform} already exists in your account`)])];Preview({...parsed,fileName:file.name});}catch(e){toast(`Could not read workbook: ${e.message}`);}finally{Busy(false);event.target.value='';}};
  const confirm=async()=>{if(!preview)return;if(preview.errors.length){toast('Fix invalid rows in the workbook before importing. Valid rows are shown below.');return;}if(mode==='replace'&&!window.confirm('Replace all of your saved Daily Log, fuel, and shift records with the valid rows from this workbook? This cannot be undone.'))return;Busy(true);try{const result=await api('/import',{method:'POST',body:JSON.stringify({...preview,mode})});await refresh();Preview(null);toast(`Imported ${result.logs} work rows, ${result.fuel} fuel records, and ${result.shifts} shifts.`);}catch(e){toast(`Import failed: ${e.message}`);}finally{Busy(false);}};
  const exportAll=()=>{const wb=XLSX.utils.book_new(),add=(name,headerRow,headers,records)=>{const rows=Array.from({length:headerRow},()=>[]);rows.push(headers);records.forEach(record=>rows.push(record));XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(rows),name);};add('Daily Log',4,['Date','Platform','Hours Worked','Orders / Deliveries','Odometer Start (km)','Odometer End (km)','Manual km (if no odometer)','Earnings (€)','Tips / Bonus (€)','Fuel Override (€) optional','Maintenance / Repairs (€)','Other Work Costs (€)','Personal Expense (€)','Notes'],data.logs.map(x=>[dateKey(x.work_date),x.platform,x.hours,x.orders_count,x.odo_start,x.odo_end,x.manual_km,x.earnings,x.tips,x.fuel_override,x.maintenance,x.other_cost,x.personal_expense,x.notes]));add('Fuel',10,['Date','Odometer (km)','Litres','Total Paid (€)','Full Tank','Station','Notes'],data.fuel.map(x=>[dateKey(x.fill_date),x.odometer,x.litres,x.total_paid,x.full_tank!==false,x.station,x.notes]));add('Shift Data',0,['Date','Shift 1','Hours 1','Shift 2','Hours 2','Notes'],data.shifts.map(x=>[dateKey(x.work_date),x.shift1,x.hours1,x.shift2,x.hours2,x.notes]));XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet([[JSON.stringify(data.settings)]]),'Settings');const lists=XLSX.utils.aoa_to_sheet([['Months','Platforms'],...['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'].map((m,i)=>[m,data.settings.platforms[i]||''])]);XLSX.utils.book_append_sheet(wb,lists,'Lists');XLSX.writeFile(wb,'courier-ledger-backup.xlsx');};
  const exportLogs=()=>exportRows('courier-daily-log.xlsx',data.logs.map(x=>({...x,distance_km:distanceOf(x),fuel_cost: fuelFor(x,data.logs,data.fuel,data.settings),total_income:number(x.earnings)+number(x.tips)})),'Daily Log');
  const exportFuel=()=>exportRows('courier-fuel.xlsx',data.fuel.map(x=>({...x,price_per_litre:number(x.litres)?number(x.total_paid)/number(x.litres):0})),'Fuel');
  return <><PageIntro title="Import / Export" detail="Preview a workbook before importing. Download your records as Excel backups at any time."/><div className="dashboard-grid"><section className="card form-card"><SectionHead title="Import Courier Finance workbook" detail="Reads saved values from Daily Log, Fuel, Shift Planner, Dashboard and Lists."/><label className="upload-box">{busy?'Reading workbook…':'Choose .xlsx workbook'}<input type="file" accept=".xlsx,.xls" disabled={busy} onChange={select}/></label>{preview&&<><h3>{preview.fileName}</h3><div className="import-counts"><span>{preview.logs.length} Daily Log rows</span><span>{preview.fuel.length} fill-ups</span><span>{preview.shifts.length} shifts</span><span>{preview.duplicates.length} duplicate date/platform pairs</span></div><label className="import-mode">Import mode<select value={mode} onChange={e=>Mode(e.target.value)}><option value="append">Append / update imported rows</option><option value="replace">Replace all saved ledger records</option></select></label>{preview.errors.length>0&&<div className="import-errors"><b>{preview.errors.length} row issues</b><ul>{preview.errors.slice(0,30).map((x,i)=><li key={i}>{x}</li>)}</ul>{preview.errors.length>30&&<span>Showing first 30 issues.</span>}</div>}{preview.duplicates.length>0&&<p className="hint">Repeated date/platform pairs were found. They remain separate rows. Review them before confirming.</p>}<div className="table-wrap"><table><thead><tr><th>DATE</th><th>PLATFORM</th><th>HOURS</th><th>EARNINGS</th><th>NOTES</th></tr></thead><tbody>{preview.logs.slice(0,10).map(x=><tr key={x.source_key}><td>{x.work_date}</td><td>{x.platform}</td><td>{x.hours}</td><td>{money(x.earnings)}</td><td>{x.notes}</td></tr>)}</tbody></table></div><div className="form-actions"><button className="soft-button" onClick={()=>Preview(null)}>Discard preview</button><button className="primary" disabled={busy||preview.errors.length>0} onClick={confirm}>{busy?'Importing…':'Confirm import'} →</button></div></>}</section><section className="card"><SectionHead title="Export and backup" detail="These exports use your saved account data."/><div className="export-actions"><button className="soft-button" onClick={exportLogs}>Export Daily Log (Excel)</button><button className="soft-button" onClick={exportFuel}>Export Fuel records (Excel)</button><button className="soft-button" onClick={exportAll}>Download full backup (Excel)</button><button className="soft-button" onClick={()=>{const csv=XLSX.utils.sheet_to_csv(XLSX.utils.json_to_sheet(data.logs));const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='courier-daily-log.csv';a.click();URL.revokeObjectURL(a.href);}}>Export Daily Log (CSV)</button></div><div className="hint">Exports include saved source values. Calculated Daily Log distance, fuel cost and income are added to its Excel export.</div><div className="entry-count">{data.logs.length} work rows · {data.fuel.length} fuel records · {data.shifts.length} planned days</div></section></div></>;
}
